import datetime

from ta_moler.events.emssim.genericemssim_lineevent import GenericEMSSIMLineEvent


class ReceivedRtpmMessage(GenericEMSSIMLineEvent):
    """ReceivedRtpmMessage event class."""

    # 13:24:38 RTPM    <|Received RTPM message (v3.2)
    _re_received_rtpm_message = r"RTPM\s+<\|Received RTPM message"

    def __init__(self, connection, till_occurs_times=1, runner=None):
        """
        Event for ReceivedRtpmMessage.

        :param connection: moler connection to device, terminal when command is executed
        :param till_occurs_times: number of event occurrence
        """
        super(ReceivedRtpmMessage, self).__init__(
            connection=connection,
            runner=runner,
            till_occurs_times=till_occurs_times,
            detect_patterns=[
                ReceivedRtpmMessage._re_received_rtpm_message,
            ],
            match="any",
        )
        self.process_full_lines_only = True


EVENT_OUTPUT_received_rtpm_message = r"""
13:24:38 RTPM    <|Received RTPM message (v3.2)
"""

EVENT_KWARGS_received_rtpm_message = {}

EVENT_RESULT_received_rtpm_message = [
    {
        "groups": (),
        "line": "13:24:38 RTPM    <|Received RTPM message (v3.2)",
        "matched": "RTPM    <|Received RTPM message",
        "named_groups": {},
        "time": datetime.datetime(2020, 4, 10, 13, 24, 38, 269854),
    }
]
